/* Icons, used as data: URIs. Two sources, each with its own helper:

   PIR — the pirate/nautical set dropped in src/icons/*.svg (a hand-picked
   pack, white paths on a transparent 0 0 512 512 canvas). Used wherever it
   has a real match: cannons for guns, a figurehead for `figure`, a sinking
   ship for wreck markers, a bandana'd skull for `noto` deliberately
   DIFFERENT from the plain skull-and-crossbones battle marker, and so on.
   Each entry's trailing comment names the source file in src/icons/, so a
   future pass can go find the same one again rather than reverse-engineer
   a path.

   MAT — Google Material Symbols (Rounded, filled — fonts.google.com/icons,
   Apache 2.0), kept wherever the pirate set has nothing that fits: `sea`,
   `plate`, `star`, `scales`, `tobacco`, `metal`, `bell`, `speed`, `time`,
   `lock`, `crew`, `mats`. Forcing a bad pirate-set fit onto one of these
   would read worse than the plain Material glyph it would replace.

   Both sources use a top-left origin with y increasing downward — same
   convention as the 0 0 24 24 box every caller here already assumes (the
   chip renderer, the map's inline markers, the icon-size checker), so each
   helper only has to fix the SCALE, never flip an axis:

     pir: source canvas is 512x512  ->  scale(24/512) = scale(.046875)
     mat: source canvas is 960x960, BUT Google roots it at y=-960 rather
          than y=0 (viewBox="0 -960 960 960"), so mat additionally shifts
          y by +960 before scaling: x'=x*.025, y'=(y+960)*.025

   Nothing downstream of this file needs to know either source uses a
   different box than the one it draws in.

   Drop a real PNG at img/icon_<name>.png and it silently replaces the
   generated placeholder — same convention as the ship art. */

const ICON_COLOR = {
  gold: '#efe3ae', cargo: '#c8a97a', mats: '#9fb8bd', barrels: '#d9883a',
  sea: '#7ab0e0', plate: '#9fb8bd', guns: '#d9883a', rig: '#cfe3e4', hold: '#c8a97a',
  relic: '#d9c98a', flag: '#efe3ae', star: '#efe3ae', anchor: '#63c06a',
  figure: '#e0b98a',
  skull: '#e8a89c', bicorne: '#f0b0a6', warrant: '#e8705c', wreck: '#7ab0e0',
  wheel: '#d9c98a', map: '#7ab0e0', port: '#c8a97a', scales: '#c8a97a',
  /* trade goods */
  rum: '#b5701f', sugar: '#e0d6bd', tobacco: '#8a6a32', wine: '#8f3050', spice: '#c9702a',
  /* materials */
  wood: '#a9834e', metal: '#9fb8bd', cloth: '#d6cfba',
  /* salvage */
  chest: '#d9c98a', bell: '#c98a4a',
  /* at-a-glance stats */
  speed: '#8fd8e8', power: '#e8b06a', hull: '#9fb8bd', time: '#bcd8f0',
  noto: '#d9c98a', depth: '#7ab0e0', target: '#f0b0a6', dest: '#c8a97a',
  danger: '#e0a03a', crew: '#cfe3e4', lock: '#6d8288'
};

/* Wrap one path from src/icons/*.svg (see header) and return it as a
   `colour => markup` function — the shape every entry in ICONS, and every
   caller of glyphBody(), already expects. */
const pir = d => c => `<g transform="scale(.046875)"><path fill="${c}" d="${d}"/></g>`;

/* Same, for a Google Material Symbols path (see header for why the 960 box
   needs the extra +24 shift that the 512 box above does not). */
const mat = d => c => `<g transform="translate(0,24) scale(.025)"><path fill="${c}" d="${d}"/></g>`;

